struct Request { n: u64, reply: oneshot::Sender<u64> } // return address in the value

async fn service(mut rx: mpsc::Receiver<Request>) {
    while let Some(req) = rx.recv().await {
        let _ = req.reply.send(fib(req.n));  // Err => requester gone
    }
}

let (tx, rx) = oneshot::channel();
mailbox.send(Request { n: 10, reply: tx }).await?;
let answer = rx.await?;

